def chk3(items, w=128):
    return table(["", "😀", "🙂", "😕"], [[x, '<span class="chk"></span>', '<span class="chk"></span>', '<span class="chk"></span>'] for x in items], [f"{w}mm", "18mm", "18mm", "18mm"])


def doc(t, n=""):
    return f'<div class="card" style="{SERIF};background:#FAF7FD;font-size:10.4pt">{H} {("<b>" + n + "</b> ") if n else ""}{t}</div>'


def frise(ev, a, b, w=180, step=10, hide=None, title=""):
    """Frise chronologique en SVG. ev = [(année, "texte|2e ligne"), …] ; hide="label" → ①②… à compléter, hide="date" → dates à compléter."""
    X = lambda y: 30 + (y - a) * 540 / (b - a)
    out = [f'<text x="300" y="12" font-size="11" font-weight="700" text-anchor="middle">{title}</text>' if title else ""]
    out.append(f'<line x1="22" y1="80" x2="582" y2="80" stroke="#1F2A44" stroke-width="3"/><path d="M582 74 L594 80 L582 86Z" fill="#1F2A44"/>')
    y = a
    while y <= b:
        out.append(f'<line x1="{X(y):.1f}" y1="76" x2="{X(y):.1f}" y2="84" stroke="#1F2A44"/><text x="{X(y):.1f}" y="95" font-size="8" text-anchor="middle" fill="#6b7385">{y}</text>')
        y += step
    for i, (yr, t) in enumerate(ev):
        x = X(yr)
        up = i % 2 == 0
        y2 = 44 if up else 112
        out.append(f'<line x1="{x:.1f}" y1="80" x2="{x:.1f}" y2="{y2}" stroke="{MC}" stroke-width="1.4"/><circle cx="{x:.1f}" cy="80" r="4" fill="{MC}"/>')
        lab = t.split("|")
        if hide == "label":
            lab = ["①②③④⑤⑥⑦⑧⑨"[i]]
        dt = "______" if hide == "date" else ("" if hide == "label" else str(yr))
        ty = 18 if up else 124
        out.append(f'<text x="{x:.1f}" y="{ty}" font-size="10" font-weight="700" text-anchor="middle" fill="{MC}">{dt}</text>')
        for k, l in enumerate(lab):
            out.append(f'<text x="{x:.1f}" y="{ty + 11 + 10 * k}" font-size="9" text-anchor="middle">{l}</text>')
    return f'<svg viewBox="0 0 600 150" width="{w}mm" style="max-width:100%;height:auto" font-family="Poppins,DejaVu Sans" fill="#1F2A44">{"".join(out)}</svg>'


PERIODES = [("Préhistoire", "#C9A27E", "les premiers humains", "→ vers 3300 av. J.-C.", "invention de l'écriture"),
            ("Antiquité", "#E8B04B", "Égypte, Grèce, Rome", "→ 476", "chute de l'Empire romain d'Occident"),
            ("Moyen Âge", "#5B8E7D", "châteaux, cathédrales", "→ 1492", "Colomb arrive en Amérique"),
            ("Temps modernes", "#4A7BD1", "imprimerie, grandes découvertes", "→ 1789", "Révolution française"),
            ("Époque contemporaine", "#9B5DE5", "industrie, guerres mondiales, Belgique", "→ aujourd'hui", "")]


def periodes(blank_names=False):
    cells = ""
    for i, (n, c, d, f, ev) in enumerate(PERIODES):
        nm = "______________" if blank_names else n
        cells += (f'<div style="flex:1;background:{c};color:#fff;padding:2mm 1.5mm;text-align:center;{"border-radius:2mm 0 0 2mm;" if i == 0 else ""}{"border-radius:0 2mm 2mm 0;" if i == 4 else ""}">'
                  f'<b style="font-size:10.5pt">{nm}</b><div class="xs" style="opacity:.95">{d}</div></div>')
    marks = "".join(f'<div style="flex:1;text-align:right;font-size:8pt;line-height:1.2;padding-right:1mm"><b>{f.replace("→ ", "")}</b><br><span class="muted">{ev}</span></div>' for n, c, d, f, ev in PERIODES)
    return f'<div style="display:flex;gap:0">{cells}</div><div style="display:flex;margin-top:1mm">{marks}</div>'


